I think it's a bug related to .NET. 
I'm using C++/WinRT and everything works like a charm:

Foo.cpp:

```cpp
#define UNICODE
#include <iostream>
#include <winrt/Windows.Foundation.Collections.h>
#include <winrt/windows.storage.h>
#include <winrt/windows.storage.streams.h>

using namespace winrt::Windows;
using namespace Storage;
using namespace Storage::Streams;
using namespace Foundation;

IAsyncAction request(const StreamedFileDataRequest request)
{
    auto writer = DataWriter();
    writer.WriteBytes({'h', 'e', 'l', 'l', 'o'});
    auto buffer = writer.DetachBuffer();
    co_await request.WriteAsync(buffer);
}

IAsyncAction create()
{
    auto file = co_await StorageFile::CreateStreamedFileAsync(L"test.txt", &request, nullptr);
    auto folder = co_await StorageFolder::GetFolderFromPathAsync(L"path/to/directory");
    co_await file.CopyAsync(folder, L"test.txt");
}

int main()
{
    winrt::init_apartment();
    create().get();
    winrt::uninit_apartment();
}
```

Build with msvc (or clang):
```
cl Foo.cpp OneCore.lib /std:c++latest /EHsc /await /FeFoo.exe
```

I'm testing it against .NET Native to see whether the issue exists in Release build.

UPD: no fortune.
